<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="csrf-token" content="{{ csrf_token() }}"><title>Dashboard CS NADI</title><style>
body{font:14px system-ui;margin:0;background:#f5f7fb;color:#27354b}header{background:#164b81;color:white;padding:18px 24px}main{max-width:1350px;padding:20px;margin:auto}.stats,.columns{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.columns{grid-template-columns:360px 1fr}.card{background:white;border:1px solid #e3e8ef;border-radius:14px;padding:16px}button,textarea{font:inherit;border:1px solid #dce3ed;border-radius:9px;padding:10px}button{cursor:pointer;background:#1766a1;color:white;border:0}.secondary{background:#eff3f8;color:#203a55}.tabs{display:flex;gap:8px;margin:14px 0}.item{padding:12px;margin:8px 0;border:1px solid #e5e9ef;border-radius:10px;cursor:pointer}.item:hover{background:#f2f7fc}.msgs{height:400px;overflow:auto;background:#f8fafc;padding:12px;border-radius:12px}.bubble{padding:10px;margin:8px 0;background:#e5eaf1;border-radius:12px;max-width:80%;white-space:pre-wrap;overflow-wrap:anywhere;width:fit-content}.mine{background:#d8e9ff;margin-left:auto}.row{display:flex;gap:8px}.row textarea{flex:1}.muted{color:#687b90;font-size:12px}#error{color:#b31b2b}#reviews{display:none}.review{padding:14px;margin:10px 0;border:1px solid #eee;border-radius:12px}@media(max-width:800px){.columns,.stats{grid-template-columns:1fr}}
</style></head><body><header><h2 style="margin:0">Dashboard Customer Service NADI</h2><small>Antrean chat, percakapan aktif, dan balasan ulasan pasien</small></header><main><div class="card" style="margin-bottom:12px;display:flex;gap:12px;align-items:center;flex-wrap:wrap"><label>Status CS <select id="presence"><option value="offline">Offline</option><option value="online">Online</option><option value="busy">Sibuk</option></select></label><span class="muted" id="notify">Notifikasi: 0</span><button class="secondary" id="reportBtn" type="button">Laporan & SLA</button><span class="muted">Antrean diprioritaskan berdasarkan tiket terlama.</span></div><div id="reportPanel" class="card" style="display:none;margin-bottom:12px"></div><div id="error" role="alert"></div><div class="stats"><div class="card">Menunggu CS <h2 id="waiting">0</h2></div><div class="card">Chat saya <h2 id="mine">0</h2></div><div class="card">Selesai hari ini <h2 id="done">0</h2></div></div><div class="tabs"><button id="chatTab">Live Chat</button><button id="reviewTab" class="secondary">Ulasan Pasien</button></div><div id="chats" class="columns"><div class="card"><div class="tabs"><button class="secondary" data-status="waiting">Menunggu</button><button class="secondary" data-status="active">Chat Saya</button><button class="secondary" data-status="closed">Riwayat</button></div><div id="queue"></div></div><div class="card"><h3 id="ticket">Pilih tiket percakapan</h3><div class="muted" id="detail"></div><div class="msgs" id="messages"></div><form id="sendForm" class="row" hidden><textarea id="msg" rows="2" maxlength="3000" required placeholder="Balas pasien..."></textarea><button>Kirim</button></form><div class="tabs"><button id="claim" hidden>Ambil Chat</button><button id="close" hidden class="secondary">Selesaikan Chat</button><button id="transfer" hidden class="secondary">Transfer ke CS</button></div></div></div><div id="reviews" class="card"><h3>Ulasan pasien</h3><p class="muted">Ulasan yang sudah masuk langsung ditampilkan; balasan CS tersimpan terpisah dari ulasan pasien.</p><div id="reviewList"></div><button id="moreReviews" class="secondary">Muat berikutnya</button></div></main><script>
const base='/cs/nadi';let mode='waiting',selected=null,lastId=0,busy=false,reviewPage=1;
async function req(path,opt={}){const r=await fetch(base+path,{credentials:'same-origin',headers:{'Accept':'application/json','Content-Type':'application/json','X-CSRF-TOKEN':document.querySelector('meta[name="csrf-token"]').content},...opt});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||'HTTP '+r.status);return d}
function err(e){document.querySelector('#error').textContent=e.message||String(e)}
async function list(){try{const d=await req('/chats?status='+mode);document.querySelector('#waiting').textContent=d.stats.waiting;document.querySelector('#mine').textContent=d.stats.mine;document.querySelector('#done').textContent=d.stats.closed_today;const q=document.querySelector('#queue');q.replaceChildren();for(const s of d.sessions){let el=document.createElement('div');el.className='item';el.textContent=s.ticket+' · '+(s.patient_name||'Pasien')+' · '+s.category+' · '+s.status;el.onclick=()=>select(s);q.append(el)}}catch(e){err(e)}}
function select(s){selected=s;lastId=0;document.querySelector('#messages').replaceChildren();document.querySelector('#ticket').textContent=s.ticket;document.querySelector('#detail').textContent=(s.patient_name||'Pasien')+' · '+s.category+' · '+s.status;document.querySelector('#claim').hidden=s.status!=='waiting';document.querySelector('#close').hidden=s.status!=='active';document.querySelector('#transfer').hidden=s.status!=='active';document.querySelector('#sendForm').hidden=s.status!=='active';if(s.status==='waiting'){document.querySelector('#messages').textContent='Tiket menunggu CS. Klik Ambil Chat untuk mulai melayani pasien.'}else loadMessages()}
async function loadMessages(){if(!selected||selected.status==='waiting'||busy)return;busy=true;try{const d=await req('/chats/'+selected.id+'/messages?after='+lastId);selected=d.session;document.querySelector('#sendForm').hidden=selected.status!=='active';document.querySelector('#close').hidden=selected.status!=='active';document.querySelector('#transfer').hidden=selected.status!=='active';for(const m of d.messages){lastId=Math.max(lastId,m.id);let el=document.createElement('div');el.className='bubble '+(m.sender_type==='cs'?'mine':'');el.textContent=m.message;document.querySelector('#messages').append(el)}if(d.messages.length)document.querySelector('#messages').scrollTop=document.querySelector('#messages').scrollHeight}catch(e){err(e)}finally{busy=false}}
document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{mode=b.dataset.status;selected=null;document.querySelector('#messages').replaceChildren();document.querySelector('#ticket').textContent='Pilih tiket percakapan';document.querySelector('#claim').hidden=true;document.querySelector('#close').hidden=true;document.querySelector('#transfer').hidden=true;document.querySelector('#sendForm').hidden=true;list()});
document.querySelector('#claim').onclick=async()=>{if(!selected)return;const claimedId=selected.id;try{await req('/chats/'+selected.id+'/claim',{method:'POST',body:'{}'});mode='active';selected=null;await list();const updated=await req('/chats?status=active');const mine=updated.sessions.find(x=>Number(x.id)===Number(claimedId));if(mine)select(mine)}catch(e){err(e)}};
document.querySelector('#close').onclick=async()=>{if(!confirm('Tandai chat selesai?'))return;try{await req('/chats/'+selected.id+'/close',{method:'POST',body:JSON.stringify({reason:'Selesai ditangani'})});selected=null;mode='waiting';list()}catch(e){err(e)}};
document.querySelector('#sendForm').onsubmit=async e=>{e.preventDefault();try{await req('/chats/'+selected.id+'/messages',{method:'POST',body:JSON.stringify({message:document.querySelector('#msg').value})});document.querySelector('#msg').value='';loadMessages()}catch(e){err(e)}};
document.querySelector('#chatTab').onclick=()=>{document.querySelector('#chats').style.display='grid';document.querySelector('#reviews').style.display='none'};
document.querySelector('#reviewTab').onclick=()=>{document.querySelector('#chats').style.display='none';document.querySelector('#reviews').style.display='block';reviewPage=1;document.querySelector('#reviewList').replaceChildren();loadReviews()};
async function loadReviews(){try{const d=await req('/reviews?page='+reviewPage);for(const r of d.data){const el=document.createElement('div');el.className='review';const title=document.createElement('b');title.textContent=(r.patient_name||'Pasien')+' · '+(r.rating??'-')+'/5'+(r.focus_category?' · '+r.focus_category:'');const p=document.createElement('p');p.textContent=r.content;const area=document.createElement('textarea');area.rows=2;area.style.width='100%';area.value=r.reply||'';area.placeholder='Balasan resmi CS';const btn=document.createElement('button');btn.textContent=r.reply?'Perbarui Balasan':'Kirim Balasan';btn.onclick=async()=>{try{await req('/reviews/'+encodeURIComponent(r.id)+'/reply',{method:'POST',body:JSON.stringify({reply:area.value})});btn.textContent='Balasan tersimpan'}catch(e){err(e)}};el.append(title,p,area,btn);document.querySelector('#reviewList').append(el)}document.querySelector('#moreReviews').hidden=!d.next_page_url;reviewPage++}catch(e){err(e)}}
document.querySelector('#moreReviews').onclick=loadReviews;document.querySelector('#presence').onchange=async(e)=>{try{await req('/presence',{method:'POST',body:JSON.stringify({status:e.target.value})});localStorage.setItem('nadi_cs_presence',e.target.value)}catch(x){err(x)}};
async function syncPresence(){const status=localStorage.getItem('nadi_cs_presence')||'offline';document.querySelector('#presence').value=status;try{await req('/presence',{method:'POST',body:JSON.stringify({status})})}catch(e){err(e)}}
document.querySelector('#transfer').onclick=async()=>{try{const d=await req('/agents');const agents=d.data.filter(x=>x.status==='online');const answer=prompt('ID CS tujuan yang online: '+agents.map(x=>x.cs_id).join(', '));if(!answer)return;const reason=prompt('Alasan transfer?');if(!reason)return;await req('/chats/'+selected.id+'/transfer',{method:'POST',body:JSON.stringify({target_cs_id:Number(answer),reason})});selected=null;mode='waiting';list();alert('Chat berhasil dialihkan')}catch(e){err(e)}};
document.querySelector('#reportBtn').onclick=async()=>{try{const d=await req('/reports');const panel=document.querySelector('#reportPanel');panel.style.display=panel.style.display==='none'?'block':'none';panel.textContent='Periode '+d.period.from+' s.d. '+d.period.to+' | Total: '+d.sessions.total+' | Selesai: '+d.sessions.closed_count+' | Menunggu: '+d.sessions.waiting_count+' | Rata-rata respons pertama (menit): '+(d.avg_first_response_minutes??'-')+' | Rating CS: '+(d.feedback.average_rating??'-')+'/5'}catch(e){err(e)}};
async function notifications(){try{const d=await req('/notifications');document.querySelector('#notify').textContent='Notifikasi: '+d.data.length;if(d.data.length && window.Notification && Notification.permission==='granted') {const first=d.data[0];if(window._lastNadiNotification!==first.id){window._lastNadiNotification=first.id;new Notification('NADI CS',{body:first.message})}}}catch(e){err(e)}}
if(window.Notification && Notification.permission==='default')document.querySelector('#notify').onclick=()=>Notification.requestPermission();
syncPresence();list();notifications();setInterval(()=>{syncPresence();list();loadMessages();notifications()},5000);
</script></body></html>
